import { readdir, readFile, rm, stat, writeFile } from "node:fs/promises";
import path from "node:path";

const docsRoot = path.resolve(import.meta.dirname, "../content/docs/bank");
const componentsRoot = path.resolve(
  import.meta.dirname,
  "../../packages/bank-kit-later/src/components",
);
const componentsIndex = path.join(componentsRoot, "index.tsx");
const generatedBanner =
  "<!-- This file is generated by `npm run build:bank-docs`. Do not edit it directly. -->";

const words = (value) =>
  value
    .replace(/([a-z])([A-Z])/g, "$1 $2")
    .replace(/[-_]/g, " ")
    .replace(/\b\w/g, (letter) => letter.toUpperCase());

const slugFrom = (value) =>
  value
    .replace(/([a-z])([A-Z])/g, "$1-$2")
    .replace(/\//g, "-")
    .replace(/[^a-zA-Z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .toLowerCase();

async function getComponents() {
  const index = await readFile(componentsIndex, "utf8");
  const exports = [
    ...index.matchAll(
      /export\s*{\s*default\s+as\s+(\w+)\s*}\s*from\s*["']\.\/(.+?)["'];?/g,
    ),
  ];

  const components = await Promise.all(
    exports.map(async ([, exportName, relativePath]) => {
      const sourcePath = path.join(componentsRoot, relativePath, "index.tsx");
      try {
        await stat(sourcePath);
      } catch {
        // Ignore stale barrel exports; only documented components need a source entry point.
        return undefined;
      }

      return {
        exportName,
        sourcePath,
        slug: slugFrom(relativePath),
        title: words(exportName),
      };
    }),
  );

  return components.filter(Boolean).sort((a, b) => a.slug.localeCompare(b.slug));
}

function documentFor(component, source) {
  const usage = `import { ${component.exportName} } from "@sol-ui/bank-kit/components";

export function Example() {
  return <${component.exportName} />;
}
`;
  const cleanedSource = source
    .trim()
    .replace(/\r\n/g, "\n")
    .replace(/[ \t]+\n/g, "\n");

  return `---
title: ${component.title}
description: A reusable ${component.title.toLowerCase()} component for banking interfaces.
---

import { ComponentPreview } from "@/src/components/ui/component-preview";
import { DocTab, DocTabs } from "@/src/components/docs/tab";
import { PackageManagers } from "@/src/components/docs/package-manager";
import { ${component.exportName} } from "@sol-ui/bank-kit/components";
import { SourceCode } from "@/src/components/ui/source-code";


<ComponentPreview>
  <${component.exportName} />
</ComponentPreview>

## Installation

<DocTabs items={['Command', 'Agent']}>
  <DocTab value="Command">
    <PackageManagers
      commands={{
        cli: "npx solui@latest add ${component.slug}",
        npm: "npx solui@latest add ${component.slug}",
        pnpm: "pnpm dlx solui@latest add ${component.slug}",
        yarn: "yarn dlx solui@latest add ${component.slug}",
        bun: "bunx --bun solui@latest add ${component.slug}",
      }}
    />
  </DocTab>
  <DocTab value="Agent">
Use an MCP-compatible coding agent and ask it:

> Install the \`${component.slug}\` Sol UI component.
  </DocTab>
</DocTabs>


## Usage

<SourceCode
  content={${JSON.stringify(usage)}}
/>


## Source

<SourceCode
  content={${JSON.stringify(cleanedSource)}}
/>`;
}


async function main() {
  const components = await getComponents();
  if (!components.length) {
    throw new Error("No component exports with source entry points were found.");
  }

  await Promise.all(
    (await readdir(docsRoot)).map(async (file) => {
      if (!file.endsWith(".mdx")) return;
      const filePath = path.join(docsRoot, file);
      const contents = await readFile(filePath, "utf8");
      if (
        contents.includes(generatedBanner) ||
        contents.includes("@sol-ui/bank-kit/blocks")
      ) {
        await rm(filePath);
      }
    }),
  );

  await Promise.all(
    components.map(async (component) => {
      const source = await readFile(component.sourcePath, "utf8");
      await writeFile(
        path.join(docsRoot, `${component.slug}.mdx`),
        documentFor(component, source),
      );
    }),
  );

  console.log(`Generated ${components.length} bank component documents.`);
}

await main();
